INSERT [dbo].[KSailCalc_Configurations_Archive] ([Id], [ConfigType], [ConfigName], [ConfigJson], [Description], [IsActive], [CreatedAt], [UpdatedAt]) VALUES (17, N'WeatherCondition', N'Beaufort Scale Weather Conditions', N'[
        {
            "beaufortNumber": 0,
            "name": "Calm",
            "description": "Sea like a mirror",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 1,
            "name": "Light Air",
            "description": "Ripples without crests",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 2,
            "name": "Light Breeze",
            "description": "Small wavelets, crests of glassy appearance",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 3,
            "name": "Gentle Breeze",
            "description": "Large wavelets, crests begin to break",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 4,
            "name": "Moderate Breeze",
            "description": "Small waves, fairly frequent white horses",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 5,
            "name": "Fresh Breeze",
            "description": "Moderate waves, many white horses",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 6,
            "name": "Strong Breeze",
            "description": "Large waves, extensive white foam crests",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 7,
            "name": "Near Gale",
            "description": "Sea heaps up, white foam from breaking waves",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 8,
            "name": "Gale",
            "description": "Moderately high waves, breaking crests forming spindrift",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 9,
            "name": "Strong Gale",
            "description": "High waves, dense foam, wave crests start to roll over",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 10,
            "name": "Storm",
            "description": "Very high waves, sea surface white with foam",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 11,
            "name": "Violent Storm",
            "description": "Exceptionally high waves, sea covered with foam",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        },
        {
            "beaufortNumber": 12,
            "name": "Hurricane",
            "description": "Air filled with foam and spray, sea completely white",
            "trueWind": {
                "fromDirectionDegrees": 270
            }
        }
    ]', N'Beaufort Scale (0-12) weather conditions with wind direction only. Wind speeds (knots) calculated dynamically from Beaufort number using WMO standard scale. Apparent wind calculated dynamically based on vessel speed and course using vector mathematics. Minimal database footprint - only Beaufort number and direction stored. For WAPS (Wind Assisted Propulsion System) optimization - NOT YET USED IN CALCULATIONS.', 1, CAST(N'2026-02-20T07:25:14.8300000' AS DateTime2), CAST(N'2026-02-20T07:25:14.8300000' AS DateTime2))
GO
